import{_ as l,a0 as o,w as s,s as d,ao as p,I as r,x as a,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"BSD 的那些事 | LCTT x X-CMD","titleTemplate":false,"description":"BSD 的那些事 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"BSD 的那些事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"BSD 的那些事 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150310 FAQ--BSD","title":"BSD 的那些事","tag":"201506","desc":""},"relativePath":"201506/20150310 FAQ--BSD.md","filePath":"[post].md"}'),u={name:"201506/20150310 FAQ--BSD.md"};function S(x,e,D,B,f,b){const i=o("Link");return s(),d("div",null,[e[22]||(e[22]=p('<h1 id="bsd-的那些事" tabindex="-1">BSD 的那些事 <a class="header-anchor" href="#bsd-的那些事" aria-label="Permalink to “BSD 的那些事”">​</a></h1><p><img src="http://www.linuxvoice.com/wp-content/uploads/2015/02/faq1-large1.png" alt=""></p><h3 id="假如歷史稍有不同-今天你將聽到的是-freebsd之聲" tabindex="-1">假如歷史稍有不同，今天你將聽到的是“FreeBSD之聲”... <a class="header-anchor" href="#假如歷史稍有不同-今天你將聽到的是-freebsd之聲" aria-label="Permalink to “假如歷史稍有不同，今天你將聽到的是“FreeBSD之聲”...”">​</a></h3><p>（LCTT 譯註：本文來自“Linux之聲（LinuxVoice）”。）</p><h4 id="那麼-這個birsa-seva-dal是怎麼回事呢-難道不是一個印度的政治組織麼" tabindex="-1">那麼，這個Birsa Seva Dal是怎麼回事呢？難道不是一個印度的政治組織麼？ <a class="header-anchor" href="#那麼-這個birsa-seva-dal是怎麼回事呢-難道不是一個印度的政治組織麼" aria-label="Permalink to “那麼，這個Birsa Seva Dal是怎麼回事呢？難道不是一個印度的政治組織麼？”">​</a></h4><p>真有趣，您查閲了維基百科上“BSD”的消除分歧頁面是為了講上面這個笑話，對麼？這裏我們在討論伯克利軟件發行版（Berkeley Software Distribution），一個比您想像中用的更廣泛的操作系統家族。</p><h4 id="抱歉-我有點-hold-不住自己。那麼-這些操作系統是怎麼回事呢" tabindex="-1">抱歉，我有點 Hold 不住自己。那麼，這些操作系統是怎麼回事呢？ <a class="header-anchor" href="#抱歉-我有點-hold-不住自己。那麼-這些操作系統是怎麼回事呢" aria-label="Permalink to “抱歉，我有點 Hold 不住自己。那麼，這些操作系統是怎麼回事呢？”">​</a></h4><p>今天，主要使用的BSD操作系統有三種。他們都基於Unix，他們都開源，並且大多擔任服務器的角色，但也能當作優秀的桌面和工作站。他們運行KDE，Firefox，LibreOffice，Apache，MySQL和許多你能説得出名字的開源軟件。它們都很穩定、安全、支持許多不同的硬件。</p><h4 id="真棒-你剛才在描述gnu-linux吧" tabindex="-1">真棒！你剛才在描述GNU/Linux吧 <a class="header-anchor" href="#真棒-你剛才在描述gnu-linux吧" aria-label="Permalink to “真棒！你剛才在描述GNU/Linux吧”">​</a></h4><p>是的，Linux擁有我剛才提到的所有東西，這也是為什麼很多人從來不討論BSD。在日常的使用中，Linux和BSD並沒有太多的不同，這主要是因為他們都以Unix為基礎，並共用很多軟件。您可以登錄進遠程主機，在Vim中寫一些Python代碼，使用Mutt檢查您的email，您可能並未意識到您在使用BSD。或許您在咖啡館裏正通過網絡終端使用它，但不知道他是BSD。</p><p>兩者最大的區別在於開發模式和許可證，為了解這些，我們需要回到過去。在BSD中，B代表着加利福尼亞大學伯克利分校（University of California, Berkeley），在1980年代，那裏是開源的Unix軟件的發源地。到了90年代，基於x86的PC變得流行，許多人對在他們的家庭電腦中安裝Unix類操作系統產生了興趣。1992年，一個叫做386BSD的項目在那時發佈，提供了上述功能。</p><h4 id="那麼-所有的linux發行版那個時候在哪裏呢" tabindex="-1">那麼，所有的Linux發行版那個時候在哪裏呢？ <a class="header-anchor" href="#那麼-所有的linux發行版那個時候在哪裏呢" aria-label="Permalink to “那麼，所有的Linux發行版那個時候在哪裏呢？”">​</a></h4><p>問得好！您也許知道這一年的前一年（1991），Linus Torvalds已經發布了他的內核，當它與GNU項目結合時，變成了完整的開源操作系統。Linus那時也在關注GNU的內核（Hurd）和386BSD，並且他説過，如果那時兩個內核有一個可以正常使用，他可能就不會創造Linux了。所以，90年代的頭幾年，開源操作系統生機勃勃，沒有人知道哪個系統會最終勝出。</p><p>接下來，BSD遇到了一些麻煩。Unix最初的開發方AT&amp;T試圖從他們在操作系統方面的付出中獲得一些利益，他們聲稱BSD侵犯了他們的知識產權。此事最終以1992年的一樁訴訟結束，它極大的抑制了BSD的開發進程。其結果就是，許多BSD源碼必須重寫，與此同時，GNU/Linux已經豐富了功能，變得穩定和流行了。</p><p>在90年代早期，BSD被認為比GNU/Linux更加成熟，如果沒有那些法律麻煩，他可能已經成為了x86 PC的標準了。今天，我們可能都在使用它而不是Linux。</p><h4 id="但你提到bsd仍然被廣泛的使用-所以它後來有提升麼" tabindex="-1">但你提到BSD仍然被廣泛的使用，所以它後來有提升麼？ <a class="header-anchor" href="#但你提到bsd仍然被廣泛的使用-所以它後來有提升麼" aria-label="Permalink to “但你提到BSD仍然被廣泛的使用，所以它後來有提升麼？”">​</a></h4><p>是的。386BSD的開發停滯了，但有兩隻開發團隊通過互聯網協作並創造了兩個獨立的成功的項目。FreeBSD成為了使用最廣泛的BSD版本，它目前是和Linux最相似的系統，包括桌面和服務器版本。而NetBSD則聚焦於可移植性（今天它可以運行在超過50種不同平台上，均基於同樣的代碼版本）。另一個版本是OpenBSD，它在NetBSD開始不久就因為開發者的口角而作為NetBSD的分支誕生了，今天，它以專注於安全聞名。多年以來，OpenBSD創建了許多程序，它們都成了Linux的標準部分，比如説OpenSSH - 甚至，現在我們還有了LibreSSL。</p><h4 id="所以-這三種版本的bsd和linux發行版相似麼" tabindex="-1">所以，這三種版本的BSD和Linux發行版相似麼？ <a class="header-anchor" href="#所以-這三種版本的bsd和linux發行版相似麼" aria-label="Permalink to “所以，這三種版本的BSD和Linux發行版相似麼？”">​</a></h4><p>也是也不是，每個BSD版本都有自己的代碼庫、不同的開發團隊。儘管他們間有許多共用的代碼（尤其是硬件驅動）。但他們是各自擁有其特色、優點和缺點的相互獨立的操作系統。</p><p>我們提到過，BSD的開發模式是他們真正和GNU/Linux區別的重要特點。在GNU/Linux中沒有人對其整體進行掌控：一些團隊在GNU組件方面工作，一些團隊在開發內核，一些在開發啓動腳本，一些在寫手冊，一些在寫庫等等。這樣的開發模式通常被稱作缺少中央權利的“荒蠻的美國西部”，由發行版負責將所有的東西各自鍥合。</p><p>而BSD則相反，它們從中央化的源代碼樹中開發並作為一個整體。內核、庫、系統組件和文檔頁都存在一個地方，且以同樣的方式使用。許多BSD粉絲聲稱，這個特點給了操作系統更多的一致性和穩定性。通過我這些年使用BSD的經驗來看，我們可以證明手冊頁已經變得非常完備。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2015/02/faq2-large1.png" alt=""></p><h4 id="難道bsd沒有使用gnu-linux的任何東西麼" tabindex="-1">難道BSD沒有使用GNU/Linux的任何東西麼？ <a class="header-anchor" href="#難道bsd沒有使用gnu-linux的任何東西麼" aria-label="Permalink to “難道BSD沒有使用GNU/Linux的任何東西麼？”">​</a></h4><p>是的，但除了GCC。幾十年來，GNU Compiler Collection已經成為了實際上的Unix系統標準編譯器，但FreeBSD最近已經轉而使用LLVM/Clang了。值得注意的是BSD還是用了一些其他的開源項目，但它們並屬於GNU或者Linux，比如説X Window System（XFree86和X.org）、Perl等等。並且幸虧有像POSIX一樣的標準，許多運行在Linux上的程序可以在BSD的許多版本上編譯和運行。</p><p>因此，您可以把LAMP（Linux、Apache、MySQL和PHP）中的L改成FreeBSD，這樣可以獲得幾乎同樣的環境，以及一些不同的特性（例如，在文件系統和驅動支持方面）。FreeBSD有一些大型、海量的用户，例如Netflix，每天提供海量的數據。儘管FreeBSD可以做為一個不錯的桌面環境，但它的長處在於服務器方面，它擁有超乎尋常的可靠性和網絡性能。</p><p>OpenBSD更傾向用於安全性十分必要的場合，如小型Web服務、文件託管、防火牆和網關。NetBSD是BSD主要發行版中最不流行的一個，它能運行在幾乎所有平台上，包括古老的Amigas和Acorn boxes，有時您可以在閉源的網絡設備中找到它的身影。</p><h4 id="等等-怎麼會有人將開源代碼閉源呢-那在linux中是不合適的" tabindex="-1">等等，怎麼會有人將開源代碼閉源呢？那在Linux中是不合適的 <a class="header-anchor" href="#等等-怎麼會有人將開源代碼閉源呢-那在linux中是不合適的" aria-label="Permalink to “等等，怎麼會有人將開源代碼閉源呢？那在Linux中是不合適的”">​</a></h4><p>對的，這裏我們談到了它與GNU/Linux的主要不同。BSD版本的許可證（很有趣，就叫做BSD許可證）非常不同於我們所知的GPL。對於新手來説，BSD更簡短。BSD許可證主要內容是：對這份代碼做你想做的事，但要保留它的初始開發者的榮譽，並且如果它搞壞你的電腦時不要提出訴訟。</p><p>因此，該許可證中沒有任何條款強制代碼開源，不像GPL，它要求使用這份代碼的用户將他們的修改也開源。這一重要的不同引起了互聯網上無數的激烈討論，BSD的粉絲們説他們的許可證更加自由（因為它不那麼嚴格），而GNU/GPL的粉絲説他們的證書才更自由（因為它保留了真正的自由）</p><h4 id="啊呀-不管怎麼説-你已經引起了我的興趣-我在哪裏能嘗試這些可愛的bsd版本呢" tabindex="-1">啊呀，不管怎麼説，你已經引起了我的興趣，我在哪裏能嘗試這些可愛的BSD版本呢？ <a class="header-anchor" href="#啊呀-不管怎麼説-你已經引起了我的興趣-我在哪裏能嘗試這些可愛的bsd版本呢" aria-label="Permalink to “啊呀，不管怎麼説，你已經引起了我的興趣，我在哪裏能嘗試這些可愛的BSD版本呢？”">​</a></h4>',30)),r("p",null,[e[4]||(e[4]=a("您大概已經可以猜到這些網站了 – ",-1)),n(i,{href:"http://www.openbsd.org/"},{default:t(()=>[...e[0]||(e[0]=[a("www.openbsd.org",-1)])]),_:1}),e[5]||(e[5]=a("、",-1)),n(i,{href:"http://www.freebsd.org/"},{default:t(()=>[...e[1]||(e[1]=[a("www.freebsd.org",-1)])]),_:1}),e[6]||(e[6]=a("、",-1)),n(i,{href:"http://www.netbsd.org/"},{default:t(()=>[...e[2]||(e[2]=[a("www.netbsd.org",-1)])]),_:1}),e[7]||(e[7]=a("。在那裏，您可以下載ISO鏡像，在VirtualBox中啓動它們，然後開始玩耍。如果您已經用了一段時間的Linux，你就會發現這並不難，雖然您需要了解命令列。如果您在尋找一些對新手更加友好的東西，可以試試PC-BSD，PC-BSD(",-1)),n(i,{href:"http://www.pcbsd.org/"},{default:t(()=>[...e[3]||(e[3]=[a("www.pcbsd.org",-1)])]),_:1}),e[8]||(e[8]=a(")是一個基於FreeBSD的個性化定製版本，它專注於桌面，有美觀的圖形化安裝器和超級簡單的軟件管理器。",-1))]),e[23]||(e[23]=r("p",null,"祝你玩的愉快！",-1)),e[24]||(e[24]=r("hr",null,null,-1)),r("p",null,[e[10]||(e[10]=a("via: ",-1)),n(i,{href:"http://www.linuxvoice.com/faq-bsd-2/"},{default:t(()=>[...e[9]||(e[9]=[a("http://www.linuxvoice.com/faq-bsd-2/",-1)])]),_:1})]),r("p",null,[e[14]||(e[14]=a("作者：",-1)),n(i,{href:"http://www.linuxvoice.com/author/mike/"},{default:t(()=>[...e[11]||(e[11]=[a("Mike Saunders",-1)])]),_:1}),e[15]||(e[15]=a(" 譯者：",-1)),n(i,{href:"https://github.com/wwy-hust"},{default:t(()=>[...e[12]||(e[12]=[a("wwy-hust",-1)])]),_:1}),e[16]||(e[16]=a(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[13]||(e[13]=[a("wxy",-1)])]),_:1})]),r("p",null,[e[19]||(e[19]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[17]||(e[17]=[a("LCTT",-1)])]),_:1}),e[20]||(e[20]=a(" 原創翻譯，",-1)),n(i,{href:"http://linux.cn/"},{default:t(()=>[...e[18]||(e[18]=[a("Linux中國",-1)])]),_:1}),e[21]||(e[21]=a(" 榮譽推出",-1))])])}const m=l(u,[["render",S]]);export{h as __pageData,m as default};
